{"content":""use client"

import { motion } from "motion/react"
import { ArrowRight } from "lucide-react"
import { Button } from "@/components/ui/button"
import DownloadButtons from "./DownloadButtons"
import type { LatestRelease } from "@/lib/types"

const APP_URL = process.env.NEXT_PUBLIC_APP_URL ?? "https://app.codr.works"

export default function DownloadSection({
  release,
}: {
  release: LatestRelease | null
}) {
  return (
    <section className="relative overflow-hidden py-28 text-center" id="download">
      <div
        className="pointer-events-none absolute top-1/2 left-1/2 h-100 w-150 -translate-x-1/2 -translate-y-1/2 bg-[radial-gradient(ellipse,rgba(129,66,199,0.15),transparent_70%)] blur-2xl"
        aria-hidden
      />
      <div className="relative z-10 mx-auto max-w-285 px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.5 }}
        >
          <h2 className="mb-4 text-[clamp(32px,5vw,52px)] font-extrabold tracking-[-0.035em]">
            Ready to code smarter?
          </h2>
          <p className="mb-10 text-lg text-muted-foreground">
            Download Codr and start shipping faster today.
          </p>
          <div className="flex flex-wrap items-center justify-center gap-4">
            {release && (
              <DownloadButtons
                assets={release.assets}
                version={release.version}
                variant="section"
              />
            )}
            <Button asChild variant="ghost" size="lg">
              <motion.a
                href={APP_URL}
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.97 }}
                className="h-auto gap-2 rounded-[14px] px-6 py-3.5 text-base"
              >
                Open remote app
                <ArrowRight className="size-4" />
              </motion.a>
            </Button>
          </div>
        </motion.div>
      </div>
    </section>
  )
}
"}
